import { initTRPC } from '@trpc/server';

/**
 * Represents the request context for tRPC procedures.
 * Contains the userId extracted from the x-user-id header.
 */
export interface Context {
  userId: string;
}

/**
 * Initialize tRPC with the context type.
 * This is used to create routers and procedures.
 */
const t = initTRPC.context<Context>().create();

export const router = t.router;
export const publicProcedure = t.procedure;

import { publicProcedure, router } from './init';

/**
 * The main tRPC router for the application.
 * Defines all available procedures.
 */
export const appRouter = router({
  /**
   * Returns the user ID extracted from the x-user-id request header.
   * Falls back to 'anonymous' if the header is not present.
   */
  getUser: publicProcedure.query(({ ctx }) => {
    return { userId: ctx.userId };
  }),
});

/**
 * The AppRouter type is used by the client to infer types.
 */
export type AppRouter = typeof appRouter;

import { fetchRequestHandler } from '@trpc/server/adapters/fetch';
import { appRouter } from '@/trpc/router';
import type { Context } from '@/trpc/init';

/**
 * Creates the tRPC context for each incoming request.
 *
 * Reads the `x-user-id` header from the incoming `Request` object.
 * If the header is present, its value is used as the userId.
 * Otherwise, falls back to `'anonymous'`.
 */
const createContext = async ({ req }: { req: Request }): Promise<Context> => {
  const userId = req.headers.get('x-user-id') ?? 'anonymous';
  return { userId };
};

/**
 * Handles all tRPC requests for the App Router.
 * Uses `fetchRequestHandler` which is the recommended approach for
 * Next.js App Router with tRPC v11.
 */
const handler = (req: Request) =>
  fetchRequestHandler({
    endpoint: '/api/trpc',
    req,
    router: appRouter,
    createContext,
  });

export { handler as GET, handler as POST };
